const data = $json;

const topic = data.topic || 'L automatisation Salesforce par IA';
const keywords = data.keywords || ['Salesforce', 'IA', 'automatisation'];
const tone = data.tone || 'expert';
const length = data.length || 'medium'; // short, medium, long

const wordCount = {short: 500, medium: 1000, long: 2000}[length];

const prompt = `Tu es un expert en rédaction SEO B2B pour le secteur Salesforce/CRM.

Écris un article de blog complet sur:
Sujet: ${topic}
Mots-clés SEO: ${keywords.join(', ')}
Ton: ${tone}
Longueur: ~${wordCount} mots

Structure requise:
1. Titre accrocheur (H1) avec mot-clé principal
2. Introduction (hook + problématique)
3. 3-5 sections (H2) avec contenu substantiel
4. Exemples concrets ou cas d'usage
5. Conclusion avec call-to-action
6. Meta description (155 caractères max)

Réponds en JSON:
{
  "title": "...",
  "meta_description": "...",
  "content": "...(format Markdown avec ## pour H2)...",
  "keywords_used": [...]
}`;

return [{json: {topic, keywords, tone, length, word_count: wordCount, prompt}}];

const prepData = $("Prepare Request").first().json;
const r = $json.response || '';

let article = {
  title: prepData.topic,
  meta_description: '',
  content: r,
  keywords_used: prepData.keywords
};

try {
  const jsonMatch = r.match(/\{[\s\S]*title[\s\S]*content[\s\S]*\}/);
  if (jsonMatch) {
    article = {...article, ...JSON.parse(jsonMatch[0])};
  }
} catch(e) {
  // Si pas de JSON, utiliser la réponse brute comme contenu
  article.content = r;
}

return [{json: {
  ...article,
  topic: prepData.topic,
  tone: prepData.tone,
  target_length: prepData.word_count,
  actual_length: article.content.split(/\s+/).length,
  generated_at: new Date().toISOString()
}}];
